fn solve(r1: i8, c1: i8, r2: i8, c2: i8) -> Vec<i8> {
    // Rook moves:
    // 0 if same square,
    // 1 if same row or same column,
    // else 2

    // Specification:
    // Requires: squares are on a standard 8x8 chessboard (1..=8)
    // Ensures: the returned vector has exactly three elements:
    //   [rook_moves, bishop_moves, king_moves]
    // where rook_moves ∈ {0,1,2} and correctly represents the minimal rook moves
    // bishop_moves ∈ {0,1,2} and correctly represents minimal bishop moves or 0 if unreachable
    // king_moves equals the Chebyshev distance between (r1,c1) and (r2,c2)

    // Additionally, bishop_moves = 0 if positions are same or different colored squares.

    requires(1 <= r1 && r1 <= 8);
    requires(1 <= c1 && c1 <= 8);
    requires(1 <= r2 && r2 <= 8);
    requires(1 <= c2 && c2 <= 8);

    ensures(|result: &Vec<i8>| result.len() == 3);

    // Rook minimal moves calculation
    let rook_moves = if r1 == r2 && c1 == c2 {
        0
    } else if r1 == r2 || c1 == c2 {
        1
    } else {
        2
    };

    // Bishop moves:
    // 0 if same square,
    // 1 if on same diagonal,
    // 2 if same color but not same diagonal,
    // 0 if different color (unreachable)

    // We break down the conditions to specify bishop moves properly

    let same_square = r1 == r2 && c1 == c2;
    let on_same_diagonal = (r1 + c1) == (r2 + c2) || (r1 - c1) == (r2 - c2);
    let same_color = ((r1 + c1) % 2) == ((r2 + c2) % 2);

    ensures(|result: &Vec<i8>| {
        let bishop = result[1];
        // bishop moves possible values
        (bishop == 0 && (same_square || !same_color))
        || (bishop == 1 && on_same_diagonal && !same_square)
        || (bishop == 2 && same_color && !on_same_diagonal && !same_square)
    });

    let bishop_moves = if same_square {
        0
    } else if on_same_diagonal {
        1
    } else if same_color {
        2
    } else {
        0
    };

    // King moves: minimal number of moves = max(abs(r1-r2), abs(c1-c2))

    let row_diff = if r1 > r2 { r1 - r2 } else { r2 - r1 };
    let col_diff = if c1 > c2 { c1 - c2 } else { c2 - c1 };
    let king_moves = std::cmp::max(row_diff, col_diff);

    ensures(|result: &Vec<i8>| {
        let king = result[2];
        king as i8 == king_moves
    });

    vec![rook_moves, bishop_moves, king_moves]
}